SINA_SMART["infect-hiv"] = {"lecture":"infect-hiv","title":"HIV/AIDS infection","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"infect-hiv:e0","text":"HIV: chronic, no cure, no vaccine, lifelong ART, near-normal life expectancy with treatment.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e1","text":"HIV-1 worldwide; HIV-2 West Africa.","topic":"Virus and epidemiology","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e2","text":"Target: CD4+ T cells (90% of infected cells).","topic":"Virus and epidemiology","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e3","text":"Morocco: prevalence ~0.08%, concentrated in key populations, mainly heterosexual.","topic":"Virus and epidemiology","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e4","text":"PrEP: TDF/FTC daily, until 2 days after last exposure.","topic":"Transmission and prevention","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e5","text":"PEP: triple therapy within 4 h (max 48-72 h) for 4 weeks.","topic":"Transmission and prevention","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e6","text":"Mother-to-child: 25-40% untreated → < 1% with ARVs and no breastfeeding.","topic":"Transmission and prevention","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e7","text":"Screening: 4th-generation ELISA (Ab + p24) or rapid test; confirm with viral load.","topic":"Diagnosis","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e8","text":"5 Cs of testing: consent, counselling, confidentiality, correct results, connection to care.","topic":"Diagnosis","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e9","text":"CD4 < 200: Pneumocystis, toxoplasmosis; < 100: cryptococcus, CMV, MAC.","topic":"Opportunistic infections and staging","sec":4,"importance":"core","highYield":"untested"},{"id":"infect-hiv:e10","text":"ART: 2 NRTIs + NNRTI or PI or integrase inhibitor, for life.","topic":"Treatment","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"rmac5p":"a","85rp1q":"a","wx5wgp":"a","25g5tr":"a","mb3mog":"a","176o8az":"a","4use79":"a","4t61zg":"a","u8iw5v":"a","xit7zi":"a","6gzgiq":"a","1sachvc":"a","1hnbv6z":"a","19ly080":"a","14v35f2":"a","p96zlg":"a","qflgq0":"a"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"infect-hiv:e0":{"s":0,"u":["HIV: chronic, no cure, no vaccine, lifelong ART, near-normal life expectancy with treatment.","Before antiretroviral therapy (ART) it was fatal; with ART it is a chronic, slowly progressive disease with near-normal life expectancy , but there is no cure and no vaccine , and treatment is lifelong ."],"dp":[]},"infect-hiv:e1":{"s":1,"u":["HIV-1 worldwide; HIV-2 West Africa.","HIV-1 is worldwide; HIV-2 mostly West Africa.","Worldwide about 40.8 million people live with HIV (end 2024), two thirds in Africa."],"dp":[]},"infect-hiv:e2":{"s":1,"u":["Target: CD4+ T cells (90% of infected cells).","Main target: CD4+ T lymphocytes (90% of infected cells; high-affinity receptor), also brain glial cells."],"dp":[]},"infect-hiv:e3":{"s":1,"u":["Morocco: prevalence ~0.08%, concentrated in key populations, mainly heterosexual.","In Morocco national prevalence is about 0.08% , a concentrated epidemic in key populations (people who inject drugs, sex workers, men who have sex with men), with mainly heterosexual transmission; the 25-44 age group is most affected."],"dp":[]},"infect-hiv:e4":{"s":2,"u":["PrEP: TDF/FTC daily, until 2 days after last exposure.","Prevention: abstinence, fidelity, condoms, PrEP (tenofovir/emtricitabine) for HIV-negative adults over 18, HBV-vaccinated, with regular risk: 1 tablet daily, continued until 2 days after the last intercourse; it does not protect against other STIs or hepatitis C."],"dp":[]},"infect-hiv:e5":{"s":2,"u":["PEP: triple therapy within 4 h (max 48-72 h) for 4 weeks.","Post-exposure prophylaxis : triple therapy as soon as possible, ideally within 4 h and no later than 48-72 h , for 4 weeks ."],"dp":[]},"infect-hiv:e6":{"s":2,"u":["Mother-to-child: 25-40% untreated → < 1% with ARVs and no breastfeeding.","Mother-to-child transmission (pregnancy, delivery, breastfeeding): 25-40% without treatment, under 1% with maternal ARVs, no breastfeeding, delivery mode adapted to viral load, and ARV syrup for the newborn for 1 month.","Routes: sexual, blood, mother-to-child ."],"dp":[]},"infect-hiv:e7":{"s":3,"u":["Screening: 4th-generation ELISA (Ab + p24) or rapid test; confirm with viral load.","Screening : fourth-generation ELISA (antibodies + p24 antigen , shorter window) or a rapid test (TROD) on serum, plasma or whole blood in under 30 minutes; saliva self-tests exist in some pharmacies.","Confirmation : plasma viral load ; Western blot only for discordant cases (positive screen, undetectable load: HIV-2, elite controllers)."],"dp":[{"h":"Why an undetectable viral load protects partners","t":"Transmission depends on how much virus is present in blood and genital fluids. When ART keeps the viral load undetectable, there is too little virus to infect a partner, so treatment is itself prevention. That is why the lecture lists 'reduce HIV transmission' among the goals of ART, not just individual health. Source: the lecture's objectives of ARV treatment slide."}]},"infect-hiv:e8":{"s":3,"u":["5 Cs of testing: consent, counselling, confidentiality, correct results, connection to care.","Testing follows the 5 Cs : consent, counselling, confidentiality, correct results, connection to care; offered, never imposed or done without the patient's knowledge."],"dp":[]},"infect-hiv:e9":{"s":4,"u":["CD4 < 200: Pneumocystis, toxoplasmosis; < 100: cryptococcus, CMV, MAC.","They appear as CD4 fall: candidiasis, TB and Kaposi first; Pneumocystis and toxoplasmosis around 200 ; cryptococcosis, CMV and lymphomas around 100 .","Opportunistic infections: tuberculosis , Pneumocystis pneumonia , cerebral toxoplasmosis , CMV retinitis , oesophageal candidiasis, cryptococcal meningitis , lymphoma, Kaposi sarcoma , cryptosporidiosis, HIV encephalitis."],"dp":[{"h":"Why the CD4 count predicts which infection appears","t":"Different pathogens need different degrees of immune failure to cause disease. Tuberculosis and candidiasis can break through a mildly weakened system, while Pneumocystis, toxoplasmosis and then CMV and cryptococcus only emerge when CD4 cells fall very low. The count therefore tells you what to look for and when to start preventive treatment. Source: the lecture's CD4 and clinical manifestations slide."}]},"infect-hiv:e10":{"s":5,"u":["ART: 2 NRTIs + NNRTI or PI or integrase inhibitor, for life.","Regimen: 2 NRTIs + 1 NNRTI, or 1 protease inhibitor, or 1 integrase inhibitor : at least three drugs, without interruption, for life (the integrated provirus persists), with strict adherence and attention to interactions and comorbidities.","ARV targets: reverse transcriptase (NRTI, NNRTI), protease, integrase, attachment/fusion."],"dp":[]}},"meta":{"rmac5p":{"a":"recall","vg":"infect-hiv:e0/recall/1"},"85rp1q":{"a":"recall","vg":"infect-hiv:e1/recall/1"},"wx5wgp":{"a":"recall","vg":"infect-hiv:e2/recall/1"},"25g5tr":{"a":"recall","vg":"infect-hiv:e3/recall/1"},"mb3mog":{"a":"recall","vg":"infect-hiv:e3/recall/2"},"176o8az":{"a":"recall","vg":"infect-hiv:e4/recall/1"},"4use79":{"a":"recall","vg":"infect-hiv:e5/recall/1"},"4t61zg":{"a":"recall","vg":"infect-hiv:e5/recall/1"},"u8iw5v":{"a":"recall","vg":"infect-hiv:e6/recall/1"},"xit7zi":{"a":"recall","vg":"infect-hiv:e7/recall/1"},"6gzgiq":{"a":"recall","vg":"infect-hiv:e7/recall/2"},"1sachvc":{"a":"recall","vg":"infect-hiv:e8/recall/1"},"1hnbv6z":{"a":"recall","vg":"infect-hiv:e8/recall/2"},"19ly080":{"a":"recall","vg":"infect-hiv:e9/recall/1"},"14v35f2":{"a":"recall","vg":"infect-hiv:e9/recall/2"},"p96zlg":{"a":"recall","vg":"infect-hiv:e10/recall/1"},"qflgq0":{"a":"relationship","vg":"infect-hiv:e0/relationship/1"}},"explRev":"c818b093fefa"};
